b_spouse_death = observation(entity='Alice', entity_source='s30', predicate='died', predicate_source='s3')  
b_remarriage = observation(entity='Bob', entity_source='s30', predicate='married', predicate_source='s9')  
b_joint_return = observation(entity='Bob', entity_source='s30', predicate='could have been made', predicate_source='s10')  
@scope('s0')  
def definitions_scope():  
    return True  
@scope('s1')  
def surviving_spouse_scope():  
    return definitions_scope  
@scope('s2')  
def general_surviving_spouse_scope():  
    return surviving_spouse_scope  
@scope('s3')  
def general_surviving_spouse_definition_scope():  
    return general_surviving_spouse_scope  
@scope('s4')  
def spouse_death_scope():  
    return general_surviving_spouse_definition_scope and b_spouse_death  
@scope('s5')  
def dependent_child_scope():  
    return general_surviving_spouse_definition_scope and b_spouse_death and b_joint_return  
@scope('s6')  
def household_maintenance_scope():  
    return general_surviving_spouse_definition_scope and b_spouse_death and b_joint_return  
@rule('s9', otherwise=False)  
def remarriage_exclusion():  
    return surviving_spouse_scope and b_remarriage  
@rule('s10', otherwise=False)  
def joint_return_exclusion():  
    return surviving_spouse_scope and (not b_joint_return)  
query = ('Entailment' if (not remarriage_exclusion and not joint_return_exclusion) else 'Contradiction')
